'use client'
import { useEffect, useState } from 'react'
import { supabase } from '@/lib/supabase'
import Link from 'next/link'

export default function HeroAdminPage() {
  const [heroes, setHeroes] = useState([])
    const [loading, setLoading] = useState(true)
      const [editingId, setEditingId] = useState(null)
        const [uploading, setUploading] = useState(false)
          const [gallery, setGallery] = useState([])
            const [showGallery, setShowGallery] = useState(false)
              const [galleryTarget, setGalleryTarget] = useState('image_url')
                const [form, setForm] = useState({
                    title: '', subtitle: '', badge_text: '', description: '',
                        media_type: 'image', image_url: '', video_url: '', mobile_image_url: '',
                            cta_text: 'Shop Collection', cta_link: '/products',
                                animation_type: 'fade-zoom', duration: 5, is_active: true, sort_order: 0
                                  })

                                    useEffect(()=>{ load() }, [])

                                      async function load() {
                                          setLoading(true)
                                              const { data } = await supabase.from('hero_sections').select('*').order('sort_order', {ascending:true})
                                                  setHeroes(data||[])
                                                      const { data: m1 } = await supabase.from('media').select('*').order('created_at',{ascending:false}).limit(40)
                                                          const { data: m2 } = await supabase.from('media_library').select('*').order('created_at',{ascending:false}).limit(40)
                                                              const combined = [...(m1||[]), ...(m2||[])]
                                                                  setGallery(combined)
                                                                      setLoading(false)
                                                                        }

                                                                          async function uploadFile(e, target) {
                                                                              const file = e.target.files[0]; if(!file) return
                                                                                  setUploading(true)
                                                                                      const isVideo = file.type.startsWith('video')
                                                                                          const fileName = `hero-${Date.now()}-${file.name}`
                                                                                              try {
                                                                                                    const { error } = await supabase.storage.from('media').upload(fileName, file)
                                                                                                          if(error) throw error
                                                                                                                const { data } = supabase.storage.from('media').getPublicUrl(fileName)
                                                                                                                      setForm(f=>({...f, [target]: data.publicUrl, media_type: target==='video_url' || isVideo ? 'video' : f.media_type }))
                                                                                                                          } catch(err) {
                                                                                                                                alert('Bucket "media" Public ON කරලා නෑ - Supabase Dashboard -> Storage -> New Bucket -> media -> Public ON')
                                                                                                                                      const reader = new FileReader()
                                                                                                                                            reader.onload = () => {
                                                                                                                                                    setForm(f=>({...f, [target]: reader.result, media_type: target==='video_url' || isVideo ? 'video' : f.media_type }))
                                                                                                                                                            setUploading(false)
                                                                                                                                                                  }
                                                                                                                                                                        reader.readAsDataURL(file)
                                                                                                                                                                              return
                                                                                                                                                                                  }
                                                                                                                                                                                      setUploading(false)
                                                                                                                                                                                        }

                                                                                                                                                                                          async function save(e) {
                                                                                                                                                                                              e.preventDefault()
                                                                                                                                                                                                  const payload = {
                                                                                                                                                                                                        ...form,
                                                                                                                                                                                                              duration: parseInt(form.duration) || 5,
                                                                                                                                                                                                                    sort_order: parseInt(form.sort_order) || 0
                                                                                                                                                                                                                        }
                                                                                                                                                                                                                            if(editingId) {
                                                                                                                                                                                                                                  await supabase.from('hero_sections').update(payload).eq('id', editingId)
                                                                                                                                                                                                                                      } else {
                                                                                                                                                                                                                                            await supabase.from('hero_sections').insert([payload])
                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                    setEditingId(null)
                                                                                                                                                                                                                                                        setForm({title:'',subtitle:'',badge_text:'',description:'',media_type:'image',image_url:'',video_url:'',mobile_image_url:'',cta_text:'Shop Collection',cta_link:'/products',animation_type:'fade-zoom',duration:5,is_active:true,sort_order:0})
                                                                                                                                                                                                                                                            load()
                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                function editHero(h){
                                                                                                                                                                                                                                                                    setEditingId(h.id)
                                                                                                                                                                                                                                                                        setForm({
                                                                                                                                                                                                                                                                              title: h.title||'', subtitle: h.subtitle||'', badge_text: h.badge_text||'', description: h.description||'',
                                                                                                                                                                                                                                                                                    media_type: h.media_type||'image', image_url: h.image_url||'', video_url: h.video_url||'', mobile_image_url: h.mobile_image_url||'',
                                                                                                                                                                                                                                                                                          cta_text: h.cta_text||'Shop Collection', cta_link: h.cta_link||'/products',
                                                                                                                                                                                                                                                                                                animation_type: h.animation_type||'fade-zoom', duration: h.duration||5, is_active: h.is_active ?? true, sort_order: h.sort_order||0
                                                                                                                                                                                                                                                                                                    })
                                                                                                                                                                                                                                                                                                        window.scrollTo({top:0, behavior:'smooth'})
                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                            async function remove(id){
                                                                                                                                                                                                                                                                                                                if(!confirm('Delete slide?')) return
                                                                                                                                                                                                                                                                                                                    await supabase.from('hero_sections').delete().eq('id', id)
                                                                                                                                                                                                                                                                                                                        load()
                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                            if(loading) return <div className="min-h-screen bg-black text-white flex items-center justify-center text-sm">Loading...</div>

                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                  <div className="min-h-screen bg-[#050505] text-white">
                                                                                                                                                                                                                                                                                                                                        <div className="max-w-6xl mx-auto p-6">
                                                                                                                                                                                                                                                                                                                                                <div className="flex justify-between items-center mb-6">
                                                                                                                                                                                                                                                                                                                                                          <h1 className="text-xl font-semibold">Hero Slider - 5s Auto + Video</h1>
                                                                                                                                                                                                                                                                                                                                                                    <Link href="/admin/dashboard" className="px-4 py-2 bg-[#1a1a1a] border border-[#222] rounded-full text-xs">Dashboard</Link>
                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                    <div className="bg-[#111] rounded-2xl p-6 border border-[#1f1f1f] mb-8">
                                                                                                                                                                                                                                                                                                                                                                                              <form onSubmit={save} className="space-y-4">
                                                                                                                                                                                                                                                                                                                                                                                                          <div className="grid md:grid-cols-4 gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                        <div><label className="text-[11px] opacity-50">Badge</label><input value={form.badge_text} onChange={e=>setForm({...form,badge_text:e.target.value})} className="w-full mt-1 bg-[#0a0a0a] border border-[#222] rounded-xl px-3 py-2.5 text-sm" placeholder="New Arrival" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                      <div><label className="text-[11px] opacity-50">Subtitle</label><input value={form.subtitle} onChange={e=>setForm({...form,subtitle:e.target.value})} className="w-full mt-1 bg-[#0a0a0a] border border-[#222] rounded-xl px-3 py-2.5 text-sm" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div><label className="text-[11px] opacity-50">Order</label><input type="number" value={form.sort_order} onChange={e=>setForm({...form,sort_order:e.target.value})} className="w-full mt-1 bg-[#0a0a0a] border border-[#222] rounded-xl px-3 py-2.5 text-sm" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div><label className="text-[11px] opacity-50">Duration (sec)</label><input type="number" value={form.duration} onChange={e=>setForm({...form,duration:e.target.value})} className="w-full mt-1 bg-[#0a0a0a] border border-[#222] rounded-xl px-3 py-2.5 text-sm" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div><label className="text-[11px] opacity-50">Title</label><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} required className="w-full mt-1 bg-[#0a0a0a] border border-[#222] rounded-xl px-4 py-3 text-sm" placeholder="Discover Your Signature Scent" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div><label className="text-[11px] opacity-50">Description</label><textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} rows={2} className="w-full mt-1 bg-[#0a0a0a] border border-[#222] rounded-xl px-4 py-3 text-sm resize-none" /></div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="grid md:grid-cols-3 gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div><label className="text-[11px] opacity-50">Media Type</label><select value={form.media_type} onChange={e=>setForm({...form,media_type:e.target.value})} className="w-full mt-1 bg-[#0a0a0a] border border-[#222] rounded-xl px-3 py-2.5 text-sm"><option value="image">Image</option><option value="video">Video</option></select></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div><label className="text-[11px] opacity-50">Animation</label><select value={form.animation_type} onChange={e=>setForm({...form,animation_type:e.target.value})} className="w-full mt-1 bg-[#0a0a0a] border border-[#222] rounded-xl px-3 py-2.5 text-sm"><option value="fade-zoom">Fade + Zoom (Luxury)</option><option value="fade">Fade</option><option value="slide">Slide</option></select></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="flex items-end"><label className="flex items-center gap-2 text-xs bg-[#0a0a0a] border border-[#222] rounded-xl px-3 py-2.5 w-full"><input type="checkbox" checked={!!form.is_active} onChange={e=>setForm({...form,is_active:e.target.checked})} /> Active</label></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="bg-[#0a0a0a] border border-[#222] rounded-xl p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <label className="text-[11px] opacity-50">Image - Upload / Gallery</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="flex gap-2 mt-2 flex-wrap items-center">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <label className="px-4 py-2 bg-white text-black rounded-full text-xs cursor-pointer">{uploading?'Uploading...':'Upload Image'}<input type="file" accept="image/*" hidden onChange={e=>uploadFile(e,'image_url')} /></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button type="button" onClick={()=>{setGalleryTarget('image_url'); setShowGallery(true)}} className="px-4 py-2 bg-[#1a1a1a] border border-[#333] rounded-full text-xs">Gallery {gallery.length}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {form.image_url && !form.image_url.startsWith('data:') && <img src={form.image_url} className="h-10 rounded object-cover border border-[#222]" alt="" />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <input value={form.image_url} onChange={e=>setForm({...form,image_url:e.target.value})} className="w-full mt-2 bg-black border border-[#222] rounded-lg px-3 py-2 text-[11px] opacity-60" placeholder="Image URL" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="bg-[#0a0a0a] border border-[#222] rounded-xl p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <label className="text-[11px] opacity-50">Video - Upload MP4 / Gallery</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="flex gap-2 mt-2 flex-wrap items-center">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <label className="px-4 py-2 bg-white text-black rounded-full text-xs cursor-pointer">Upload Video<input type="file" accept="video/*" hidden onChange={e=>uploadFile(e,'video_url')} /></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button type="button" onClick={()=>{setGalleryTarget('video_url'); setShowGallery(true)}} className="px-4 py-2 bg-[#1a1a1a] border border-[#333] rounded-full text-xs">Gallery Video</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {form.video_url && <span className="text-[10px] text-green-400 truncate max-w-[200px]">{form.video_url.slice(0,50)}</span>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <input value={form.video_url} onChange={e=>setForm({...form,video_url:e.target.value})} className="w-full mt-2 bg-black border border-[#222] rounded-lg px-3 py-2 text-[11px] opacity-60" placeholder="Video URL mp4" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {form.video_url && <video src={form.video_url} className="mt-2 h-20 rounded border border-[#222]" muted />}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="grid md:grid-cols-2 gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div><label className="text-[11px] opacity-50">CTA Text</label><input value={form.cta_text} onChange={e=>setForm({...form,cta_text:e.target.value})} className="w-full mt-1 bg-[#0a0a0a] border border-[#222] rounded-xl px-3 py-2.5 text-sm" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div><label className="text-[11px] opacity-50">CTA Link</label><input value={form.cta_link} onChange={e=>setForm({...form,cta_link:e.target.value})} className="w-full mt-1 bg-[#0a0a0a] border border-[#222] rounded-xl px-3 py-2.5 text-sm" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="flex gap-2 justify-end pt-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {editingId && <button type="button" onClick={()=>{setEditingId(null); setForm({title:'',subtitle:'',badge_text:'',description:'',media_type:'image',image_url:'',video_url:'',mobile_image_url:'',cta_text:'Shop Collection',cta_link:'/products',animation_type:'fade-zoom',duration:5,is_active:true,sort_order:0})}} className="px-5 py-2.5 bg-[#1a1a1a] rounded-full text-xs">Cancel</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button className="px-6 py-2.5 bg-white text-black rounded-full text-xs font-medium">{editingId?'Update':'Add Slide'}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="grid md:grid-cols-3 gap-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {heroes.map(h=>(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div key={h.id} className="bg-[#111] border border-[#1f1f1f] rounded-2xl overflow-hidden">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {h.media_type==='video' && h.video_url ? <video src={h.video_url} className="w-full h-40 object-cover" muted /> : h.image_url ? <img src={h.image_url} className="w-full h-40 object-cover" alt="" /> : <div className="h-40 bg-[#0a0a0a] flex items-center justify-center text-xs opacity-20">No Media</div>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="p-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="flex justify-between"><span className="text-[10px] opacity-50">{h.badge_text} • {h.media_type} • {h.duration}s • #{h.sort_order}</span><span className={`text-[9px] px-2 py-0.5 rounded-full ${h.is_active?'bg-white text-black':'bg-red-500/20 text-red-400'}`}>{h.is_active?'Active':'Hidden'}</span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h3 className="text-sm font-medium mt-2">{h.title}</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="flex gap-2 mt-3"><button onClick={()=>editHero(h)} className="text-xs px-3 py-1 bg-white text-black rounded-full">Edit</button><button onClick={()=>remove(h.id)} className="text-xs px-3 py-1 bg-[#1a1a1a] border border-[#222] rounded-full">Delete</button></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {showGallery && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="fixed inset-0 bg-black/80 backdrop-blur z-50 flex items-center justify-center p-6">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="bg-[#111] border border-[#222] rounded-2xl p-6 max-w-3xl w-full max-h-[70vh] overflow-auto">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="flex justify-between mb-4"><h3 className="text-sm">Gallery - Click to Select - {galleryTarget}</h3><button onClick={()=>setShowGallery(false)} className="px-3 py-1 bg-[#222] rounded-full text-xs">Close</button></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="grid grid-cols-4 gap-3">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {gallery.map((it,i)=>{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const url = it.url||it.file_url||it.image_url||it.video_url||it.src; if(!url) return null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const isV = url.includes('.mp4') || it.type?.includes('video')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return <button key={i} onClick={()=>{setForm(f=>({...f,[galleryTarget]:url, media_type: isV || galleryTarget==='video_url' ? 'video' : f.media_type})); setShowGallery(false)}} className="bg-[#0a0a0a] border border-[#222] rounded-xl p-2 hover:border-white/20 overflow-hidden">{isV ? <video src={url} className="w-full h-16 object-cover rounded" muted /> : <img src={url} className="w-full h-16 object-cover rounded" alt="" />}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {gallery.length===0 && <p className="text-xs opacity-40 text-center py-10">Gallery empty</p>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          